const product = {
  name: "Weber Q2600N+",
  brand: "Weber",
  category: "Portable Gas Grill (LPG)",
  model: "Q2600N+",
  part_number: "28510024"
};

const facts = [
  { id: "FACT-001", claim: "Main burner rated at 19 MJ (18,000 BTU), plus a supplementary '+' burner rated at 4.2 MJ (4,000 BTU)", source: "Weber Australia official product page", source_url: "https://anz.weber.com/en-au/products/weber-q-q2600n-plus-lpg-gas-bbq-midnight-black", type: "manufacturer_claim" },
  { id: "FACT-002", claim: "Primary cooking area of 2,064 sq cm (57cm x 41cm), with capacity for approximately 12 burgers at once", source: "Weber Australia official product page", source_url: "https://anz.weber.com/en-au/products/weber-q-q2600n-plus-lpg-gas-bbq-midnight-black", type: "manufacturer_claim" },
  { id: "FACT-003", claim: "Porcelain-enamelled cast iron cooking grates", source: "Weber Australia official product page", source_url: "https://anz.weber.com/en-au/products/weber-q-q2600n-plus-lpg-gas-bbq-midnight-black", type: "manufacturer_claim" },
  { id: "FACT-004", claim: "Piezo push-button ignition, removable side tables, and a front-facing grease/catch tray", source: "Weber Australia official product page", source_url: "https://anz.weber.com/en-au/products/weber-q-q2600n-plus-lpg-gas-bbq-midnight-black", type: "manufacturer_claim" },
  { id: "FACT-005", claim: "Compatible with the optional Weber Connect smart grilling hub", source: "Weber Australia official product page", source_url: "https://anz.weber.com/en-au/products/weber-q-q2600n-plus-lpg-gas-bbq-midnight-black", type: "manufacturer_claim" },
  { id: "FACT-006", claim: "Listed at $589 AUD (part number 28510024), with an extended warranty of up to 15 years available on registration", source: "Weber Australia official product page", source_url: "https://anz.weber.com/en-au/products/weber-q-q2600n-plus-lpg-gas-bbq-midnight-black", type: "manufacturer_claim" }
];

const expert_findings = [
  { id: "EXP-010", finding: "The dual-burner setup (18,000 BTU main + 4,000 BTU Plus burner) delivered consistent temperatures across the cooking surface, reaching about 750F and searing steaks to medium-rare in 6-7 minutes", source: "Smoked BBQ Source independent review of the Weber Q2800N+ (the larger sibling model on the same G3 platform, not the exact Q2600N+ unit)", source_url: "https://www.smokedbbqsource.com/weber-q-2800n-plus-gas-grill-review/", type: "independent_test" },
  { id: "EXP-011", finding: "Despite weighing under 40 lbs, the grill was described as very sturdy for such a lightweight, compact, portable grill, with the porcelain-enamelled cast-iron grates giving even heat distribution and retention", source: "Smoked BBQ Source independent review of the Weber Q2800N+ (same G3 platform sibling, not the exact Q2600N+ unit)", source_url: "https://www.smokedbbqsource.com/weber-q-2800n-plus-gas-grill-review/", type: "independent_test" },
  { id: "EXP-012", finding: "The front-facing removable catch pan and compact footprint made cleanup simple, with deep cleaning only requiring occasional grate removal", source: "Smoked BBQ Source independent review of the Weber Q2800N+ (same G3 platform sibling, not the exact Q2600N+ unit)", source_url: "https://www.smokedbbqsource.com/weber-q-2800n-plus-gas-grill-review/", type: "independent_test" },
  { id: "EXP-013", finding: "The reviewer's main criticism was that pricing is similar to a full-sized Weber Spirit grill, questioning the value for a smaller unit", source: "Smoked BBQ Source independent review of the Weber Q2800N+ (same G3 platform sibling, not the exact Q2600N+ unit)", source_url: "https://www.smokedbbqsource.com/weber-q-2800n-plus-gas-grill-review/", type: "independent_test" }
];

const owner_sentiment = [
  { id: "SENT-001", topic: "overall_rating", sentiment: "positive", evidence_count: 25, detail: "4.7 out of 5 stars across 25 reviews, 96% of reviewers recommend the product", source: "The Good Guys (AU retailer) customer reviews", source_url: "https://www.thegoodguys.com.au/weber-q-2600n-plus-lp-midnight-black-28510024" },
  { id: "SENT-002", topic: "portability", sentiment: "positive", evidence_count: 25, detail: "Customers praise its lightweight, compact design for camping and small patios", source: "The Good Guys (AU retailer) customer reviews", source_url: "https://www.thegoodguys.com.au/weber-q-2600n-plus-lp-midnight-black-28510024" },
  { id: "SENT-003", topic: "ease_of_cleaning", sentiment: "positive", evidence_count: 25, detail: "Push-button ignition and removable drip tray receive consistent praise", source: "The Good Guys (AU retailer) customer reviews", source_url: "https://www.thegoodguys.com.au/weber-q-2600n-plus-lp-midnight-black-28510024" },
  { id: "SENT-004", topic: "price", sentiment: "negative", evidence_count: 25, detail: "Some customers find it expensive relative to alternatives", source: "The Good Guys (AU retailer) customer reviews", source_url: "https://www.thegoodguys.com.au/weber-q-2600n-plus-lp-midnight-black-28510024" },
  { id: "SENT-005", topic: "assembly_documentation", sentiment: "negative", evidence_count: 25, detail: "Limited assembly documentation noted; some users recommend checking online guides instead", source: "The Good Guys (AU retailer) customer reviews", source_url: "https://www.thegoodguys.com.au/weber-q-2600n-plus-lp-midnight-black-28510024" },
  { id: "SENT-006", topic: "cooking_capacity", sentiment: "mixed", evidence_count: 25, detail: "Not considered ideal for very large gatherings; seen as better suited to groups up to about 8 people", source: "The Good Guys (AU retailer) customer reviews", source_url: "https://www.thegoodguys.com.au/weber-q-2600n-plus-lp-midnight-black-28510024" }
];

return [{
  json: {
    ...$input.item.json,
    research: { product, facts, expert_findings, owner_sentiment }
  }
}];

const cfg = $input.item.json;
const research = cfg.research;

const system_prompt = `You are an evidence-based product review writer.

Your job is to transform VERIFIED PRODUCT DATA into a useful, accurate and readable product review.

STRICT RULES:
1. Use ONLY information supplied in the research data.
2. Do not invent specifications, features, prices, test results, experiences or opinions.
3. Do not claim that you personally tested or used the product.
4. Do not say "we tested" unless the supplied evidence explicitly states that our organization performed the test.
5. Do not convert manufacturer claims into independently verified facts.
6. Clearly distinguish: manufacturer claims, independent testing, owner/user opinions.
7. If evidence is conflicting, acknowledge the conflict.
8. If there is insufficient evidence for a claim, do not make the claim.
9. Do not fabricate citations or evidence IDs - every evidence_id/evidence_ids entry anywhere in your output MUST be one of the ids supplied in the research data below.
10. Do not mention information that is not supported by the input.
11. Write for a normal consumer, not an AI researcher.
12. Avoid generic filler and exaggerated marketing language.
13. Some independent-test evidence below may be drawn from a closely related sibling model rather than the exact product being reviewed (this will be stated explicitly in that evidence item's source). When you use such evidence, you MUST say so in the text (e.g. "in a review of the related Q2800N+ model...") rather than presenting it as if it were tested on this exact unit.
14. The review MUST begin with a complete Specifications section. Create exactly one specifications entry for EVERY single item in VERIFIED FACTS supplied below - do not omit, merge, skip, or summarize away any fact, even minor ones. Each entry needs a short label, the value/claim in plain language, and the evidence_id it came from. This is a full spec sheet, not a highlights list.
15. The review MUST end with a single owner_consensus that blends ALL supplied OWNER SENTIMENT entries into one coherent closing paragraph covering the full range - positive, negative, and mixed topics alike, not just the flattering ones. Its evidence_ids array must include every single owner_sentiment id supplied below; do not cherry-pick only the positive ones.
16. Do not use Markdown formatting anywhere in any string value - no **bold**, *italics*, backticks, or headings. All text fields are inserted as plain text on a web page, so literal asterisks or backticks would show up as garbage characters. Each pros/cons entry must be a single plain sentence, not a bolded label followed by a paragraph.

STRUCTURE (in this order): specifications (complete, first) -> pros/cons/sections (expert findings and general content) -> owner_consensus (complete blended close, last) -> verdict.

SCORING ("score" field, a number from 0-10):
There was previously no guidance at all for this field, and it showed - real published reviews came out scoring 0.9 and 4.0-4.5 for products (a well-regarded mechanical keyboard, flagship earbuds) with mostly positive evidence, because the model had no anchor and defaulted to grading harshly. Use this scale:
- 9-10: exceptional, standout in its category, evidence shows few or no meaningful flaws.
- 7-8: strong recommendation, does its job well, only minor/niche caveats.
- 5-6: solid and usable, but with real trade-offs a buyer should know about.
- 3-4: below average, notable flaws outweigh the strengths in the evidence.
- 0-2: reserve for products the evidence shows are seriously broken, unsafe, or not fit for purpose - this should be rare.
The presence of SOME cons is normal and does not by itself justify a low score - nearly every real product has cons. Base the score on the overall balance of verified facts, expert findings, and owner sentiment: if that balance is mostly positive with only minor caveats, score it 7 or higher. Do not average "number of pros vs number of cons" as if they were equally weighted evidence.

VOICE - WRITE LIKE A HUMAN REVIEWER, NOT A SPEC SHEET:
- Write with a real reviewer's voice: confident, specific, and readable, not a flat list of facts. Vary sentence rhythm across sections; do not open every section with the same template (e.g. do not start every section with 'The product offers...').
- Actively surface what real people said. When you draw on expert findings or owner sentiment, attribute it naturally in the prose using that evidence item's source name (e.g. 'One long-term owner on [source] said...', 'Testing by [source] found...', 'Several buyers mention...'), instead of presenting it as an anonymous fact. Never invent a name or outlet that is not in the supplied evidence. When sentiment rests on only one or two reports, phrase it as an individual report (e.g. 'one owner said...') rather than a broad generalization (e.g. 'buyers love...').
- Avoid generic filler and AI-review boilerplate (e.g. 'In today's market...', 'Overall, it's clear that...', 'When it comes to X...'). Every sentence should carry real, specific information drawn from the evidence, not vague praise.
- This is still an aggregated-consensus review, not a first-person test: never claim you personally tried, used, or tested the product. The human touch comes from presenting other people's real, cited opinions and findings vividly and specifically, not from inventing your own firsthand experience.

The final output MUST be valid JSON matching the requested schema. Do not output Markdown. Do not output explanations outside the JSON.`;

const user_prompt = `Create a product review from the following verified research.

PRODUCT:
${JSON.stringify(research.product)}

VERIFIED FACTS:
${JSON.stringify(research.facts)}

EXPERT FINDINGS:
${JSON.stringify(research.expert_findings)}

OWNER SENTIMENT:
${JSON.stringify(research.owner_sentiment)}

Return the review using the exact JSON schema provided in the format parameter. Remember: specifications must cover every fact above, and owner_consensus.evidence_ids must cover every owner sentiment id above.`;

const review_schema = {
  type: "object",
  properties: {
    title: { type: "string" },
    summary: { type: "string" },
    specifications: {
      type: "array",
      items: {
        type: "object",
        properties: {
          label: { type: "string" },
          value: { type: "string" },
          evidence_id: { type: "string" }
        },
        required: ["label", "value", "evidence_id"]
      }
    },
    score: { type: "number" },
    best_for: { type: "string" },
    not_best_for: { type: "string" },
    pros: { type: "array", items: { type: "string" } },
    cons: { type: "array", items: { type: "string" } },
    expert_consensus: { type: "string" },
    sections: {
      type: "array",
      items: {
        type: "object",
        properties: {
          heading: { type: "string" },
          content: { type: "string" },
          evidence_ids: { type: "array", items: { type: "string" } }
        },
        required: ["heading", "content", "evidence_ids"]
      }
    },
    owner_consensus: {
      type: "object",
      properties: {
        content: { type: "string" },
        evidence_ids: { type: "array", items: { type: "string" } }
      },
      required: ["content", "evidence_ids"]
    },
    verdict: { type: "string" }
  },
  required: ["title", "summary", "specifications", "pros", "cons", "sections", "owner_consensus", "verdict"]
};

const qa_system_prompt = `You are a strict fact-checking editor.

Review the generated product review against the supplied evidence.

For every factual claim:
1. Determine whether evidence exists.
2. Determine whether the claim accurately represents the evidence.
3. Detect unsupported claims.
4. Detect invented specifications.
5. Detect invented personal experience.
6. Detect claims that incorrectly present manufacturer statements as independent testing.
7. Detect contradictions.
8. Detect any evidence sourced from a sibling/related model that is presented as if it were tested on the exact product being reviewed, without disclosing the distinction.
9. Check the specifications array against VERIFIED FACTS: every fact id supplied must appear as a specifications[].evidence_id. Set specifications_complete to false if any fact is missing from specifications.
10. Check owner_consensus.evidence_ids against OWNER SENTIMENT: every owner_sentiment id supplied must appear there, and the written content must genuinely reflect the negative/mixed topics too, not just the positive ones. Set owner_consensus_complete to false if any sentiment id is missing or if the text only reflects positive sentiment while ignoring supplied negative/mixed sentiment.
11. confidence must be a decimal between 0 and 1 (e.g. 0.92 for 92% confidence) - never a whole number like 92 or 100.

Return JSON only, matching the requested schema.`;

const qa_schema = {
  type: "object",
  properties: {
    status: { type: "string", enum: ["PASS", "FAIL"] },
    confidence: { type: "number", minimum: 0, maximum: 1 },
    specifications_complete: { type: "boolean" },
    owner_consensus_complete: { type: "boolean" },
    issues: {
      type: "array",
      items: {
        type: "object",
        properties: {
          type: { type: "string" },
          text: { type: "string" },
          reason: { type: "string" }
        }
      }
    }
  },
  required: ["status", "confidence", "specifications_complete", "owner_consensus_complete", "issues"]
};

return [{
  json: {
    ...cfg,
    system_prompt: system_prompt + `\n\nReturn ONLY a JSON object matching exactly this schema - no markdown fences, no extra commentary:\n${JSON.stringify(review_schema)}`,
    user_prompt,
    review_schema,
    qa_system_prompt: qa_system_prompt + `\n\nReturn ONLY a JSON object matching exactly this schema - no markdown fences, no extra commentary:\n${JSON.stringify(qa_schema)}`,
    qa_schema
  }
}];

const res = $input.item.json;
const raw = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || (res.message && res.message.content) || res.response || '';

let review = null;
let parseError = null;
try {
  review = JSON.parse(raw);
} catch (e) {
  parseError = e.message;
}

const prep = $('Prepare Prompts').item.json;

let retryCount = 0;
try {
  retryCount = $('Retry Writer').item.json._retryCount;
} catch (e) {
  retryCount = 0;
}

return [{
  json: {
    review,
    _parseOk: review !== null,
    _parseError: parseError,
    research: prep.research,
    ollama_base_url: prep.ollama_base_url,
    writer_model: prep.writer_model,
    qa_model: prep.qa_model,
    qa_min_confidence: prep.qa_min_confidence,
    system_prompt: prep.system_prompt,
    user_prompt: prep.user_prompt,
    review_schema: prep.review_schema,
    qa_system_prompt: prep.qa_system_prompt,
    qa_schema: prep.qa_schema,
    _retryCount: retryCount
  }
}];

const item = $input.item.json;
const errors = [];

if (!item._parseOk) {
  errors.push(`Writer output was not valid JSON: ${item._parseError}`);
}

const review = item.review;
const required = ["title", "summary", "specifications", "pros", "cons", "sections", "owner_consensus", "verdict"];

if (review) {
  for (const field of required) {
    if (!(field in review)) errors.push(`Missing field: ${field}`);
  }
  if (review.pros && !Array.isArray(review.pros)) errors.push("pros must be an array");
  if (review.cons && !Array.isArray(review.cons)) errors.push("cons must be an array");
  if ("score" in review && typeof review.score !== "number") errors.push("score must be numeric");

  const factIds = item.research.facts.map(f => f.id);
  const expertIds = item.research.expert_findings.map(f => f.id);
  const sentimentIds = item.research.owner_sentiment.map(f => f.id);
  const validIds = new Set([...factIds, ...expertIds, ...sentimentIds]);

  if (Array.isArray(review.sections)) {
    for (const section of review.sections) {
      for (const evidenceId of (section.evidence_ids || [])) {
        if (!validIds.has(evidenceId)) {
          errors.push(`Section "${section.heading}" cites unknown evidence id: ${evidenceId}`);
        }
      }
    }
  }

  // Specifications must be a full spec sheet: one entry per supplied fact, no omissions.
  if (Array.isArray(review.specifications)) {
    const specFactIds = new Set(review.specifications.map(s => s.evidence_id));
    for (const id of factIds) {
      if (!specFactIds.has(id)) {
        errors.push(`Specifications section is missing fact ${id} - every supplied fact must appear as a specification entry`);
      }
    }
    for (const spec of review.specifications) {
      if (spec.evidence_id && !validIds.has(spec.evidence_id)) {
        errors.push(`Specification "${spec.label}" cites unknown evidence id: ${spec.evidence_id}`);
      }
    }
  } else {
    errors.push("specifications must be an array covering every supplied fact");
  }

  // owner_consensus must blend ALL supplied owner sentiment, not a subset.
  if (review.owner_consensus && typeof review.owner_consensus === "object") {
    if (!review.owner_consensus.content || typeof review.owner_consensus.content !== "string" || review.owner_consensus.content.trim().length === 0) {
      errors.push("owner_consensus.content must be a non-empty string");
    }
    const citedSentimentIds = new Set(review.owner_consensus.evidence_ids || []);
    for (const id of sentimentIds) {
      if (!citedSentimentIds.has(id)) {
        errors.push(`owner_consensus is missing owner sentiment ${id} - the closing blend must cover every supplied sentiment item, not just the positive ones`);
      }
    }
  } else {
    errors.push("owner_consensus must be an object with { content, evidence_ids } blending every supplied owner sentiment item");
  }
}

return [{
  json: {
    ...item,
    _valid: errors.length === 0,
    _errors: errors
  }
}];

const item = $input.item.json;

const feedback = `\n\nYour previous output failed validation for these reasons:\n${item._errors.map(e => `- ${e}`).join('\n')}\n\nFix these issues and return corrected JSON that strictly matches the schema and only cites evidence ids that were supplied.`;

return [{
  json: {
    ollama_base_url: item.ollama_base_url,
    writer_model: item.writer_model,
    qa_model: item.qa_model,
    qa_min_confidence: item.qa_min_confidence,
    system_prompt: item.system_prompt,
    user_prompt: item.user_prompt + feedback,
    review_schema: item.review_schema,
    qa_system_prompt: item.qa_system_prompt,
    qa_schema: item.qa_schema,
    research: item.research,
    _retryCount: (item._retryCount || 0) + 1
  }
}];

const item = $input.item.json;

const qa_user_prompt = `REVIEW TO CHECK:\n${JSON.stringify(item.review)}\n\nSUPPLIED EVIDENCE:\n${JSON.stringify(item.research)}\n\nCheck the review above against the supplied evidence and return your JSON verdict.`;

return [{
  json: {
    ollama_base_url: item.ollama_base_url,
    qa_model: item.qa_model,
    qa_system_prompt: item.qa_system_prompt,
    qa_user_prompt,
    qa_schema: item.qa_schema,
    qa_min_confidence: item.qa_min_confidence,
    review: item.review,
    research: item.research
  }
}];

const res = $input.item.json;
const raw = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || (res.message && res.message.content) || res.response || '';

let qa = null;
let parseError = null;
try {
  qa = JSON.parse(raw);
} catch (e) {
  parseError = e.message;
}

const prep = $('Prepare QA Prompt').item.json;

return [{
  json: {
    qa,
    _qaParseOk: qa !== null,
    _qaParseError: parseError,
    review: prep.review,
    research: prep.research,
    qa_min_confidence: prep.qa_min_confidence
  }
}];

const item = $input.item.json;

const approved = {
  ...item.review,
  qa: item.qa,
  approved_at: new Date().toISOString(),
  product: item.research.product
};

return [{ json: approved }];
